import { ShopError } from './errors.js';

export function applyDiscount(cents, percent) {
  if (!(percent >= 0 && percent <= 100)) {
    throw new ShopError('INVALID_PERCENT', `percent must be between 0 and 100, got ${percent}`);
  }
  return Math.floor((cents * (100 - percent)) / 100);
}

